mapper.select:
                SELECT T0.FINPROD_ID AS FINPRODID,
		               T0.FINPROD_NAME AS FINPRODNAME,
		               T0.PROFIT_TYPE AS FINPRODTYPE,
		               t2.val_date AS VALDATE,
		               NVL(T2.BUILD_STATUS, '0') AS BUILDSTATUS,
		               T2.ERROR_TYPE AS ERRORTYPE
		          from FIN_PRODUCT T0
		          inner JOIN BOK_VALBAL_TABLE_LOG T2
		            ON T0.FINPROD_ID = T2.FINPROD_ID
		           AND T2.VAL_BAL_FLAG = #{fileType}
		         where 1 = 1
		           AND T0.FINPROD_TYPE = #{finprodType}

			  			AND T0.FINPROD_ID in 

			        	#{prdId} 



			  		AND T0.PROFIT_TYPE in 

			        	#{prodType} 



					 	and t2.val_date >= #{valDateBegin,jdbcType=DATE} 


						and t2.val_date <= #{valDateEnd,jdbcType=DATE} 


			  			AND NVL(T2.BUILD_STATUS, '0') in 

			        		#{buildStatus} 


		           order by t2.VAL_DATE desc

select prd.finprod_id,nvl(prd.finprod_abbr,prd.finprod_name) finprod_abbr from fin_product prd 
	where 1=1

	AND prd.FINPROD_TYPE = #{finprodType}

SELECT FP.FINPROD_ID AS finProdId, FP.FINPROD_NAME AS finprodName, A.BOOKSET_ID booksetId, A.BAL_DATE balDate, A.O_CCY oCcy, B.VOUCH_NUM errorCount FROM (SELECT BTD.BOOKSET_ID, BTD.BAL_DATE, BTD.O_CCY, row_number() over(partition by BTD.BOOKSET_ID, BTD.BAL_DATE , BTD.O_CCY order by BTD.BOOKSET_ID, BTD.O_CCY, BTD.BAL_DATE desc) AS SEQ FROM BOK_BAL_TABLE_DATA BTD WHERE 1=1
AND BTD.BAL_DATE >= #{valDateBegin,jdbcType=DATE}
AND BTD.BAL_DATE <= #{valDateEnd,jdbcType=DATE}
) A LEFT JOIN BOK_VOUCH_MAIN_ERROR B ON A.BOOKSET_ID = B.BOOKSET_ID AND A.BAL_DATE = B.BOOK_DATE JOIN BOK_BOOKSET BB ON A.BOOKSET_ID = BB.BOOKSET_ID JOIN FIN_PRODUCT FP ON BB.ACCT_SUBJECT_ID = FP.FINPROD_ID where A.SEQ = '1'
AND FP.FINPROD_ID = #{prodId}
order by A.BOOKSET_ID, A.BAL_DATE, A.O_CCY

        SELECT COUNT(1) FROM BOK_VALBAL_TABLE_STATUS 
        WHERE 1=1

   			AND FINPROD_ID = #{prodId} 


         AND VAL_DATE>= to_date(#{valDateBegin},'yyyy-mm-dd') 


         AND VAL_DATE<= to_date(#{valDateEnd},'yyyy-mm-dd') 	

		AND CHECK_STATUS = #{checkStatus} 
		AND VAL_BAL_FLAG = #{fileType}

mapper.update:
        DELETE	FROM																																
			BOK_VALBAL_TABLE_STATUS																																
	    WHERE VAL_BAL_FLAG = #{fileType}

   			AND FINPROD_ID = #{prodId}


	    AND VAL_DATE >= #{valDateBegin,jdbcType=DATE} 


	    AND VAL_DATE <= #{valDateEnd,jdbcType=DATE}

        DELETE FROM BOK_VALBAL_TABLE_LOG 
	    WHERE VAL_BAL_FLAG = #{fileType}

     			AND FINPROD_ID = #{prodId} 


	   		 AND VAL_DATE >= #{valDateBegin,jdbcType=DATE} 


	   		 AND VAL_DATE <= #{valDateEnd,jdbcType=DATE}

mapper.select:
SELECT DISTINCT BOOKSET_ID, BOOKSET_NAME FROM BOK_BOOKSET where 1=1
AND ACCT_SUBJECT_ID = #{prodId,jdbcType=VARCHAR}
order by BOOKSET_ID
